package app.launcherin.tv;
import java.util.*;import java.net.URI;import org.schabi.newpipe.extractor.*;import org.schabi.newpipe.extractor.search.*;import org.schabi.newpipe.extractor.playlist.*;import org.schabi.newpipe.extractor.stream.*;
/** Real public catalog pages, separate from the existing playback resolver and lyric integration. */
final class LauncherinMusicCatalog {
 static final class Collection {final String name,url,art,artist;final boolean album;Collection(String n,String u,String a,String artist,boolean album){this.name=LauncherinTrack.limit(n,240);url=u;art=a;this.artist=LauncherinTrack.limit(artist,160);this.album=album;}}
 static boolean valid(String url){try{URI u=new URI(url);String h=u.getHost();if(!"https".equals(u.getScheme())||u.getPort()!=-1||u.getUserInfo()!=null||url.length()>2048)return false;return ("www.youtube.com".equals(h)||"music.youtube.com".equals(h)||"youtube.com".equals(h))&&"/playlist".equals(u.getPath())&&u.getRawQuery()!=null&&u.getRawQuery().matches("(?:[^&]*&)*list=[A-Za-z0-9_-]{1,160}(?:&.*)?")||("soundcloud.com".equals(h)||"www.soundcloud.com".equals(h))&&u.getPath().matches("/[A-Za-z0-9_-]+/sets/[A-Za-z0-9_-]+/?");}catch(Exception e){return false;}}
 static List<Collection> search(String query,boolean sc,boolean albums)throws Exception {LauncherinMusicSource.ensureInit();String q=LauncherinTrack.limit(query,160);if(q.isEmpty())return Collections.emptyList();StreamingService service=sc?ServiceList.SoundCloud:ServiceList.YouTube;SearchExtractor e=service.getSearchExtractor(q,Collections.singletonList(sc?"playlists":albums?"music_albums":"music_playlists"),"");e.fetchPage();SearchInfo info=SearchInfo.getInfo(e);List<Collection> list=new ArrayList<>();for(InfoItem item:info.getRelatedItems())if(item instanceof PlaylistInfoItem&&valid(item.getUrl())){PlaylistInfoItem p=(PlaylistInfoItem)item;list.add(new Collection(p.getName(),p.getUrl(),LauncherinMusicSource.image(p.getThumbnails()),p.getUploaderName(),albums&&!sc));if(list.size()>=20)break;}return list;}
 static List<LauncherinTrack> load(Collection collection)throws Exception {if(!valid(collection.url))throw new IllegalArgumentException("Coleção inválida");LauncherinMusicSource.ensureInit();StreamingService service=NewPipe.getServiceByUrl(collection.url);PlaylistInfo info=PlaylistInfo.getInfo(service,collection.url);List<LauncherinTrack> out=new ArrayList<>();append(info.getRelatedItems(),out,collection);Page page=info.getNextPage();int pages=0;while(out.size()<100&&Page.isValid(page)&&++pages<=3){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException();ListExtractor.InfoItemsPage<StreamInfoItem> more=PlaylistInfo.getMoreItems(service,collection.url,page);append(more.getItems(),out,collection);page=more.getNextPage();}return out;}
 private static void append(List<StreamInfoItem> items,List<LauncherinTrack> out,Collection c){for(StreamInfoItem t:items)if(out.size()<100&&LauncherinTrack.validPage(t.getUrl())&&t.getDuration()>0&&out.stream().noneMatch(x->x.url.equals(t.getUrl()))){LauncherinTrack track=new LauncherinTrack(t.getUrl(),t.getName(),t.getUploaderName(),LauncherinMusicSource.image(t.getThumbnails()),t.getDuration()*1000,t.getServiceId()==ServiceList.SoundCloud.getServiceId()?"soundcloud":"youtube",LauncherinMusicSource.image(t.getUploaderAvatars()));if(c.album)track=track.withAlbum(c.name,0);out.add(track);}}
}
